 void connect(){mixerIp=ip.getText().toString().trim();disconnect();new Thread(()->{try{socket=new DatagramSocket();socket.setSoTimeout(700);running=true;sendNow("/info");DatagramPacket p=new DatagramPacket(new byte[2048],2048);socket.receive(p);connected=true;runOnUiThread(()->{status.setText("M32R CONNECTED");status.setTextColor(Color.rgb(52,211,153));startStop.setEnabled(true);});new Thread(this::rx).start();new Thread(this::keep).start();scanRoutes();syncFromSource();}catch(Exception e){runOnUiThread(()->status.setText("NO RESPONSE"));disconnect();}}).start();}
