 void feedback(){int bi=-1;float best=0;for(int i=18;i<94;i++){if(rta[i]<-48||rta[i]<=rta[i-1]||rta[i]<=rta[i+1])continue;float s=0;int n=0;for(int j=i-4;j<=i+4;j++)if(j>=0&&j<100&&Math.abs(j-i)>=2){s+=rta[j];n++;}float ex=rta[i]-s/n;if(ex>6.5&&ex>best){best=ex;bi=i;}}if(bi<0){candStart=0;candBand=-1;return;}int band=nearBand(RF[bi]);if(band!=candBand){candBand=band;candStart=System.currentTimeMillis();return;}long held=System.currentTimeMillis()-candStart;runOnUiThread(()->candidate.setText("Feedback: "+(int)GF[candBand]+" Hz • "+held+" / "+delay()+" ms"));if(held>=delay()){int p=par(band);float old=cur.containsKey(p)?den(cur.get(p)):0;push();write(band,Math.max(-15,old-cut()));candStart=0;candBand=-1;}}
 void flat(){for(int i=0;i<31;i++){int q=nearRta(GF[i]);float s=0;int n=0;for(int j=Math.max(0,q-3);j<=Math.min(99,q+3);j++){s+=rta[j];n++;}flatAvg[i]=(flatAvg[i]*flatFrames+s/n)/(flatFrames+1f);}flatFrames++;long now=System.currentTimeMillis();if(flatFrames<24||now-lastFlatApply<5000)return;float[] cp=flatAvg.clone();Arrays.sort(cp);float ref=cp[15];push();for(int i=0;i<31;i++){float err=ref-flatAvg[i];if(Math.abs(err)<1)continue;int p=par(i);float old=cur.containsKey(p)?den(cur.get(p)):0,orig=snap.containsKey(p)?den(snap.get(p)):old;float desired=orig+Math.max(-4,Math.min(2,err*.45f));write(i,old+Math.max(-.5f,Math.min(.5f,desired-old)));}lastFlatApply=now;Arrays.fill(flatAvg,0);flatFrames=0;}
 int nearBand(float f){int b=0;double d=99;for(int i=0;i<31;i++){double x=Math.abs(Math.log(GF[i]/f));if(x<d){d=x;b=i;}}return b;}int nearRta(float f){int b=0;double d=99;for(int i=0;i<100;i++){double x=Math.abs(Math.log(RF[i]/f));if(x<d){d=x;b=i;}}return b;}void push(){undo.push(new HashMap<>(cur));if(undo.size()>12)undo.removeLast();}void write(int b,float db){float v=norm(db);cur.put(par(b),v);geq[b]=db;send(pa(par(b)),v);runOnUiThread(()->analyzer.setGeq(geq));}float norm(float d){return Math.max(0,Math.min(1,(d+15)/30));}float den(float v){return v*30-15;}void undo(){if(undo.isEmpty())return;HashMap<Integer,Float> m=undo.pop();for(Map.Entry<Integer,Float> e:m.entrySet())send(pa(e.getKey()),e.getValue());cur.clear();cur.putAll(m);readGeq();}void restore(){for(Map.Entry<Integer,Float> e:snap.entrySet())send(pa(e.getKey()),e.getValue());readGeq();}
 byte[] osc(String a,Object...x)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream(),p=new ByteArrayOutputStream();StringBuilder t=new StringBuilder(",");for(Object z:x){if(z instanceof Integer){t.append('i');p.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putInt((Integer)z).array());}else if(z instanceof Float){t.append('f');p.write(ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN).putFloat((Float)z).array());}}o.write(pad(a));o.write(pad(t.toString()));o.write(p.toByteArray());return o.toByteArray();}byte[] pad(String s)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(s.getBytes(StandardCharsets.UTF_8));o.write(0);while(o.size()%4!=0)o.write(0);return o.toByteArray();}String rs(byte[] d,int[] o){int i=o[0],e=i;while(e<d.length&&d[e]!=0)e++;String s=new String(d,i,e-i,StandardCharsets.UTF_8);o[0]=(e+4)&~3;return s;}
 TextView tv(String s,int z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);if(b)v.setTypeface(null,1);return v;}TextView lbl(String s){TextView v=tv(s,12,true);v.setTextColor(Color.LTGRAY);return v;}Button btn(String s){Button b=new Button(this);b.setText(s);return b;}Spinner sp(String[] a,int n){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));s.setSelection(n);return s;}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);return p;}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}@Override protected void onDestroy(){disconnect();super.onDestroy();}
 public static class EqView extends View{Paint p=new Paint(1);float[] rta=new float[100],g=new float[31];int mode;EqView(android.content.Context c){super(c);Arrays.fill(rta,-90);}void setRta(float[] a){rta=a.clone();invalidate();}void setGeq(float[] a){g=a.clone();invalidate();}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),top=25,bot=h-35,mid=(top+bot)/2;p.setStrokeWidth(1);p.setColor(Color.rgb(35,48,63));for(int i=0;i<=6;i++){float y=top+(bot-top)*i/6;c.drawLine(0,y,w,y,p);}boolean r=mode==2||mode==3||mode==4,bar=mode==0||mode==4,curve=mode==1||mode==3;if(r){p.setColor(Color.rgb(56,189,248));p.setStrokeWidth(2);Path q=new Path();for(int i=0;i<100;i++){float x=w*i/99f,y=top+(-Math.max(-90,Math.min(0,rta[i]))/90)*(bot-top);if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);}if(bar){float bw=w/31;p.setStrokeWidth(Math.max(3,bw*.55f));for(int i=0;i<31;i++){float x=bw*(i+.5f),y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;p.setColor(g[i]<-.1?Color.RED:g[i]>.1?Color.GREEN:Color.GRAY);c.drawLine(x,mid,x,y,p);}}if(curve){p.setColor(Color.rgb(52,211,153));p.setStrokeWidth(3);Path q=new Path();for(int i=0;i<31;i++){float x=w*i/30f,y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;if(i==0)q.moveTo(x,y);else q.lineTo(x,y);}c.drawPath(q,p);for(int i=0;i<31;i++){float x=w*i/30f,y=mid-Math.max(-15,Math.min(15,g[i]))/15*(bot-top)/2;c.drawCircle(x,y,4,p);}}p.setColor(Color.LTGRAY);p.setTextSize(14);c.drawText("20",2,h-8,p);c.drawText("100",w*.22f,h-8,p);c.drawText("1k",w*.52f,h-8,p);c.drawText("10k",w*.82f,h-8,p);c.drawText("20k",w-30,h-8,p);}}
